class SubstitutionsGroup extends HttpApiGroup.make("substitutions")
  .add(HttpApiEndpoint.get("substitutionsList", "/substitutions", { query: SubstitutionsListQuery, success: SubstitutionsList200, error: [SubstitutionsList400.pipe(HttpApiSchema.status(400)), SubstitutionsList401.pipe(HttpApiSchema.status(401)), SubstitutionsList429.pipe(HttpApiSchema.status(429)), SubstitutionsList500] })
      .annotate(OpenApi.Identifier, "substitutions.list")
      .annotate(OpenApi.Summary, "What to use instead, in what amount, and when not to.")
      .annotate(OpenApi.Description, "What to use instead of an ingredient. `ingredients` is a comma-separated list of ingredient names or canonical ids. Each option says how much to use for one unit of the original, how to handle it, and what it cannot be used for. Ingredients nothing is known to substitute for come back in `unknown` rather than with a plausible guess.")) {}

export class TinyPlatesApi extends HttpApi.make("TinyPlatesApi")
  .annotate(OpenApi.Title, "Tiny Plates API")
  .annotate(OpenApi.Version, "2.1.0")
  .annotate(OpenApi.Description, "Read API for the recipe database. Recipes are scraped from the web, then normalized into a canonical model with structured ingredients, numbered steps, times in seconds, servings, nutrition, media and classification.\n\nDocumentation: https://www.tinyplates.dev/docs, where a signed-in reader can run any endpoint against this API. Create a key at https://www.tinyplates.dev.\n\nAuthentication: an API key is required. Send it as an Authorization: Bearer header. Each account may make 50 requests a day and 300 a week, counted across all of its keys.")
  .annotate(OpenApi.Servers, [{"description":"Production.","url":"https://api.tinyplates.dev"},{"description":"Local development.","url":"http://localhost:6891"}])
  .add(HealthGroup, PantryGroup, PopularGroup, RecipesGroup, RootGroup, SearchGroup, ShoppingListGroup, IngredientsGroup, StatusGroup, SubstitutionsGroup) {}
